def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_tseitin_formula(n):
        # Generate a Tseitin formula with n variables
        var = [f'x{i}' for i in range(1, n+1)]
        clauses = []
        for i in range(n):
            clauses.append([var[i]])
            for j in range(i+1, n):
                clauses.append([f'~{var[i]}', f'~{var[j]}', var[j-i-1]])
                clauses.append([f'{var[i]}', f'{var[j]}', f'~{var[j-i-1]}'])
        return clauses

    def tseitin_to_polynomial(clauses):
        # Convert Tseitin formula to polynomial
        n = len(clauses)
        poly = [0] * (2**n)
        for clause in clauses:
            if len(clause) == 1:
                var_index = int(clause[0][1:]) - 1
                poly[1 << var_index] += 1
            else:
                term = 1
                for lit in clause:
                    if lit.startswith('~'):
                        var_index = int(lit[1:]) - 1
                        term *= (1 - (1 << var_index))
                    else:
                        var_index = int(lit) - 1
                        term *= (1 + (1 << var_index))
                poly[term] += 1
        return poly

    def find_roots(poly):
        # Find distinct roots of the polynomial
        n = len(poly)
        roots = set()
        for i in range(n):
            if poly[i] != 0:
                root = Fraction(i, 2**n)
                roots.add(root)
        return roots

    def resolution_width(clauses):
        # Compute resolution proof width
        stack = []
        visited = set()
        for clause in clauses:
            stack.append(clause)
            visited.add(tuple(sorted(clause)))

        while stack:
            clause1 = stack.pop()
            if len(clause1) == 1:
                return len(visited)

            lit = clause1[0]
            if lit.startswith('~'):
                other_lit = f'{lit[1]}'
            else:
                other_lit = f'~{lit}'

            for clause2 in clauses:
                if other_lit in clause2:
                    new_clause = [l for l in clause2 if l != other_lit]
                    if len(new_clause) == 0:
                        return len(visited)
                    stack.append(sorted(new_clause))
                    visited.add(tuple(sorted(new_clause)))

        return len(visited)

    n_values = [5, 10, 15, 20, 30, 40]
